            return (False, None)
    # Compute answer with a reasonably large bound; if not found, declare invalid
    ans = find_min_n(base, pattern, modulus1, residue1, modulus2, residue2, Nmax=15000)
    if ans is None:
        return (False, None)
    return (True, ans)
